<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('announcement.view');$pdo=staff_db();$staff=current_staff();$s=$pdo->prepare("SELECT a.* FROM announcements a WHERE a.is_active=1 AND (a.publish_at IS NULL OR a.publish_at<=NOW()) AND (a.expires_at IS NULL OR a.expires_at>=NOW()) AND (a.target_role_id IS NULL OR a.target_role_id=?) ORDER BY a.is_important DESC,a.created_at DESC");$s->execute([$staff['role_id']]);$rows=$s->fetchAll();$pageTitle='Announcements';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Company</p><h1>Announcements</h1></div></div><div class="announcement-grid"><?php foreach($rows as $r):?><article class="staff-panel announcement"><div class="rowtop"><small><?= h(date('j M Y',strtotime($r['created_at']))) ?></small><?php if($r['is_important']):?><span class="pill urgent">Important</span><?php endif;?></div><h2><?= h($r['title']) ?></h2><p><?= nl2br(h($r['content'])) ?></p></article><?php endforeach;?></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
